/** The features as a grid of cards, tiles or bordered cells (the body of FeatureGrid). Icons are Lucide names. */
import { Fragment, type ReactNode } from "react";
import { Card } from "../primitives/card/card";
import { CardContent } from "../primitives/card/card-content";
import { CardHeader } from "../primitives/card/card-header";
import { CardTitle } from "../primitives/card/card-title";
import { Grid } from "../primitives/grid/grid";
import { Group } from "../primitives/group/group";
import { IconBadge } from "../primitives/iconbadge/iconbadge";
import { LucideIcon } from "../primitives/lucide-icon/lucide-icon";
import { Stack } from "../primitives/stack/stack";
import { Text } from "../primitives/text/text";
import { Title } from "../primitives/title/title";
import { defaults } from "../presets/defaults";
import { cn } from "../utils";
import type { Feature } from "../blocks/feature-grid.types";

export type FeatureCardsProps = {
  features: Feature[];
  cols?: "1-2" | "1-3" | "1-4";
  item?: "card" | "tile" | "cell";
};

export function FeatureCards({ features, cols = "1-3", item = "card" }: FeatureCardsProps) {
  return (
    <Grid
      cols={cols}
      className={
        (item as string) === "cell" ? cn("w-full gap-px overflow-hidden bg-border p-px", defaults.features.cells)
        : "gap-6"
      }
      data-testid="feature-grid"
    >
      {(features ?? []).map((feature) => (
        <Fragment key={feature.id}>
          {((item as string) === "tile") ? (
            <Card variant="compact" data-testid="feature-card">
              <Group gap="4" align="start">
                <LucideIcon name={feature.icon} size={20} />
                <Stack gap="2">
                  <Title as={3} size="base" weight="bold">
                    {feature.title}
                  </Title>
                  <Text size="sm" className="text-muted-foreground">
                    {feature.text}
                  </Text>
                </Stack>
              </Group>
            </Card>
          ) : ((item as string) === "cell") ? (
            <Stack
              gap="2"
              align="center"
              className="h-full gap-8 bg-background px-6 py-12 text-center"
              data-testid="feature-card"
            >
              <IconBadge variant="primary" size="xl" data-testid="feature-icon">
                <LucideIcon name={feature.icon} size={24} />
              </IconBadge>
              <Title as={3} size="xl" weight="semibold" className="leading-6">
                {feature.title}
              </Title>
              <Text size="sm" weight="semibold" className="leading-5 text-muted-foreground">
                {feature.text}
              </Text>
            </Stack>
          ) : (
            <Card variant="default" data-testid="feature-card">
              <CardHeader className="flex flex-col gap-4">
                <LucideIcon name={feature.icon} size={24} />
                <CardTitle as={3}>
                  {feature.title}
                </CardTitle>
              </CardHeader>
              <CardContent>
                <Text size="sm" className="text-muted-foreground">
                  {feature.text}
                </Text>
              </CardContent>
            </Card>
          )}
        </Fragment>
      ))}
    </Grid>
  );
}
